package main

import "hash/fnv"

func hashInt(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}

type HashRing struct {
	Nodes []string
}

func NewHashRing(nodes []string, replicas int) *HashRing {
	cp := make([]string, len(nodes))
	copy(cp, nodes)
	return &HashRing{Nodes: cp}
}

func (r *HashRing) GetNode(key string) string {
	return r.Nodes[hashInt(key)%uint32(len(r.Nodes))]
}

func (r *HashRing) AddNode(node string) {
	r.Nodes = append(r.Nodes, node)
}

func (r *HashRing) RemoveNode(node string) {
	out := r.Nodes[:0]
	for _, n := range r.Nodes {
		if n != node {
			out = append(out, n)
		}
	}
	r.Nodes = out
}

