package main

import (
	"fmt"
	"testing"
)

func TestEveryKeyMapsToACurrentNode(t *testing.T) {
	ring := NewHashRing([]string{"a", "b", "c"}, 50)
	for i := 0; i < 200; i++ {
		node := ring.GetNode(fmt.Sprintf("key-%d", i))
		if node != "a" && node != "b" && node != "c" {
			t.Fatalf("unexpected node %q", node)
		}
	}
}

func TestDeterministic(t *testing.T) {
	ring := NewHashRing([]string{"a", "b", "c"}, 50)
	if ring.GetNode("stable-key") != ring.GetNode("stable-key") {
		t.Fatalf("expected deterministic mapping")
	}
}

func TestRemovingANodeOnlyMovesThatNodesOwnKeys(t *testing.T) {
	nodes := []string{"n0", "n1", "n2", "n3", "n4"}
	ring := NewHashRing(nodes, 100)
	keys := make([]string, 1000)
	for i := range keys {
		keys[i] = fmt.Sprintf("key-%d", i)
	}
	before := make(map[string]string, len(keys))
	for _, k := range keys {
		before[k] = ring.GetNode(k)
	}

	ring.RemoveNode("n2")

	moved := 0
	for _, k := range keys {
		after := ring.GetNode(k)
		if after != before[k] {
			moved++
			if before[k] != "n2" {
				t.Fatalf("key %q moved but was not on removed node n2 (was on %q)", k, before[k])
			}
		}
		if after == "n2" {
			t.Fatalf("key %q still maps to removed node n2", k)
		}
	}
	if moved == 0 {
		t.Fatalf("expected removing a node to move at least some keys")
	}
}

