package main

import (
	"fmt"
	"hash/fnv"
	"sort"
)

func hashInt(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}

type HashRing struct {
	replicas int
	ring     map[uint32]string
	sorted   []uint32
}

func NewHashRing(nodes []string, replicas int) *HashRing {
	r := &HashRing{replicas: replicas, ring: make(map[uint32]string)}
	for _, n := range nodes {
		r.AddNode(n)
	}
	return r
}

func (r *HashRing) rebuildSorted() {
	r.sorted = r.sorted[:0]
	for point := range r.ring {
		r.sorted = append(r.sorted, point)
	}
	sort.Slice(r.sorted, func(i, j int) bool { return r.sorted[i] < r.sorted[j] })
}

func (r *HashRing) AddNode(node string) {
	for i := 0; i < r.replicas; i++ {
		point := hashInt(fmt.Sprintf("%s:%d", node, i))
		r.ring[point] = node
	}
	r.rebuildSorted()
}

func (r *HashRing) RemoveNode(node string) {
	for i := 0; i < r.replicas; i++ {
		point := hashInt(fmt.Sprintf("%s:%d", node, i))
		delete(r.ring, point)
	}
	r.rebuildSorted()
}

func (r *HashRing) GetNode(key string) string {
	point := hashInt(key)
	idx := sort.Search(len(r.sorted), func(i int) bool { return r.sorted[i] >= point })
	if idx == len(r.sorted) {
		idx = 0
	}
	return r.ring[r.sorted[idx]]
}

